/* - - - ROOT - - - */

    :root {
        --background-dark: #2d3548;
        --text-normal: rgba(148, 148, 148, 0.9);
        --text-light: rgba(255, 255, 255, 0.6);
        --text-lighter: rgba(255, 255, 255, 0.9);
        --spacing-s: 8px;
        --spacing-m: 16px;
        --spacing-l: 24px;
        --spacing-xl: 32px;
        --spacing-xxl: 64px;
        --width-container: 85vw;
    }
    
    * {
        border: 0;
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }
    
    html {
        height: 100%;
        font-family: 'MerkurSans-Regular;
        font-size: 14px;
    }
    
    body {
        height: 100%;
    }

/* - - - CMS - - - */

    .content.cms-page .page-container {
        max-width: 100% !important;
    }
    
    .cms-header-container {
        display: none !important;
    }
    
    .cms-content-container {
        background-image: url('https://www.merkurbets.de/cms//public/content/images/campaignimages2023/winget/Paper_BG_White_Extra-Long.jpg') !important;
        background-size: cover !important;
    }
    
    .winget .my-container {
        margin: 0 auto;
        max-width: 85vw;
        padding-top: 5rem;
        padding-bottom: 3rem;
    }
    
    a:link, a:visited {
        color: #FFCD00;
        font-weight: 900;
    }

/* - - - MENÜ HOVER CONTAINER - - - */

    .menu {
        display: flex;
        align-items: center;
        width: 60vw;
        margin: 0 auto;
        margin-bottom: 1rem;
        margin-top: 3rem;
    }
    
    .menu-bg {
        display: flex;
        background-color: #022652;
        border-radius: 12px;
        box-shadow: 2px 2px 10px rgba(0, 0, 0, 0.5);
    }

    /* Layout und Zurücksetzen globaler Link-Styles */
    a.mein-container {
        display: inline-flex;
        align-items: center;
        gap: 15px;
        text-decoration: none; /* Entfernt eventuelle globale Unterstreichungen */
        padding: 5px 20px;
    }

    a.mein-container .mein-svg-icon {
        width: auto;
        height: 35px; /* Ihre gewünschte Desktop-Höhe */
        transition: fill 0.3s ease;
    }

    /* Standardfarben definieren */
    a.mein-container .container-text {
        color: #ffffff; /* Überschreibt Ihre globale Linkfarbe */
        transition: color 0.3s ease;
        font-size: 2.5rem;
        font-weight: 900;
    }

    a.mein-container .cls-1 {
        fill: #ffffff;
        transition: fill 0.3s ease;
    }

    /* --- HOVER EFFEKT --- */
    /* Reagiert auf den Link-Hover und färbt alles ein */
    a.mein-container:hover .container-text {
        color: #ffcc00;
        text-decoration: none; /* Verhindert Unterstreichung beim Hover, falls global aktiv */
    }

    a.mein-container:hover .cls-1 {
        fill: #ffcc00;
    }

    /* Vertikale Trennlinien zwischen den Menüpunkten */
    .mein-container:not(:last-child) {
        border-right: 2px solid #fff;
    }
    
/* - - - PROMO HEADER TEXT - - - */

    .promo-header {
        width: 60vw;
        margin: 0 auto;
        padding-top: 3rem;
        padding-bottom: 2rem;
    }

    a.promo-container {
        display: inline-flex;
        align-items: center;
        gap: 15px;
        text-decoration: none; /* Entfernt eventuelle globale Unterstreichungen */
    }

    a.promo-container .mein-svg-icon {
        width: auto;
        height: 35px; /* Ihre gewünschte Desktop-Höhe */
        transition: fill 0.3s ease;
    }

    /* Standardfarben definieren */
    a.promo-container .promo-container-text {
        color: #ffffff; /* Überschreibt Ihre globale Linkfarbe */
        transition: color 0.3s ease;
        font-size: 2.5rem;
        font-weight: 400;
    }

    a.promo-container .promo-container-text-mobile {
        color: #ffffff; /* Überschreibt Ihre globale Linkfarbe */
        transition: color 0.3s ease;
        font-size: 2rem;
        line-height: 2.5rem;
        font-weight: 400;
    }

    .promo-container-text {
        display: block;
    }

    .promo-container-text-mobile {
        display: none;
    }

    a.promo-container .cls-1 {
        fill: #ffffff;
        transition: fill 0.3s ease;
    }

    /* --- HOVER EFFEKT --- */
    /* Reagiert auf den Link-Hover und färbt alles ein */
    a.promo-container:hover .promo-container-text {
        color: #ffcc00;
        text-decoration: none; /* Verhindert Unterstreichung beim Hover, falls global aktiv */
    }

    a.promo-container:hover .promo-container-text-mobile {
        color: #ffcc00;
        text-decoration: none; /* Verhindert Unterstreichung beim Hover, falls global aktiv */
    }

    a.promo-container:hover .cls-1 {
        fill: #ffcc00;
    }

/* - - - GALLERY - - - */

    .gallery {
        display: flex;
        justify-content: center;
        align-items: center;
        gap: 2rem;
        width: 60vw;
        margin: 0 auto;
        padding-bottom: 2rem;
    }
    
    .gallery-img {
        height: 100%;
        width: 100%;
        object-fit: cover;
        border-radius: 12px;
        box-shadow: 0 10px 25px rgba(0,0,0,.15);
    }

/* - - - Image-Karussell - - - */

    .carousel {
        max-width: 100vw;
        margin: 0 auto;
    }
    
    .carousel-container {
        display: flex;
        align-items: center;
        gap: 10px;
        width: 79%;
        margin: 0 auto;
        position: relative;
        padding-bottom: 2rem;
    }
    
    .carousel-wrapper {
        overflow: hidden;
        width: 100%;
        touch-action: pan-y;
    }
    
    .carousel-track {
        display: flex;
    }
    
    .carousel-item {
        flex: 0 0 25%;
        padding: 5px 10px;
        box-sizing: border-box;
    }
    
    .carousel-item img {
        width: 100%;
        height: auto;
        object-fit: cover;
        border-radius: 12px;
        display: block;
        box-shadow: 0 10px 25px rgba(0,0,0,.15);
    }
    
    .carousel-btn {
        width: 50px;
        height: 50px;
        border: none;
        background: rgba(0,25,52,.5);
        color: #fff;
        border-radius: 50%;
        cursor: pointer;
        font-size: 22px;
        z-index: 2;
        transition: .3s;
    }
    
    .carousel-btn:hover {
        background: rgba(0,25,52,1);
    }
}

